def check_offset(offset):
    mismatches = []

    for r in range(10):
        src_r = (r + offset) % 10

        # Find dominant non-wall, non-zero value in right section of src row
        right_vals = [demo_in[src_r][c] for c in range(5, 10)]
        non_zeros = [v for v in right_vals if v not in (0, 1)]

        expected_color = None
        if non_zeros:
            expected_color = non_zeros[0]

        # Check output row - what color do holes have?
        out_row = demo_out[r]
        filled_colors = []
        for c in range(6):
            if out_row[c] != 1:  # Not a wall
                if out_row[c] not in filled_colors:
                    filled_colors.append(out_row[c])

        status = "OK"
        if expected_color is not None and filled_colors:
            if expected_color == filled_colors[0]:
                status = "✓"
            else:
                status = f"MISMATCH (expected {expected_color}, got {filled_colors})"
        elif expected_color is None and filled_colors:
            status = f"MISMATCH (expected empty, got {filled_colors})"
        elif expected_color is not None:
            status = f"MISMATCH (expected {expected_color}, got empty)"

        mismatches.append((r, src_r, status))

    return mismatches

